insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000099151', '20000000-0000-4000-8000-000000000001', '10000000-0000-4000-8000-000000000264', 'multiple_choice', 'hard', 'published', 'Ao validar uma conclusão escrita, Considere a sequência $a_n=3+\frac{1}{n+9}$. Calcule a expressão e escolha a alternativa correta.') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000991511', '40000000-0000-4000-8000-000000099151', 'A', 'É decrescente, limitada inferiormente por $3$ e converge para $3$.', 1), ('50000000-0000-4000-8000-000000991512', '40000000-0000-4000-8000-000000099151', 'B', 'Ocorre um erro de sinal ou de ordem na etapa decisiva.', 2), ('50000000-0000-4000-8000-000000991513', '40000000-0000-4000-8000-000000099151', 'C', 'A conclusão usa uma fórmula fora de suas hipóteses.', 3), ('50000000-0000-4000-8000-000000991514', '40000000-0000-4000-8000-000000099151', 'D', 'A expressão ignora uma condição necessária do enunciado.', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
